SELECT COUNT(*) as payment_attempts
FROM payments
WHERE payment_date >= '2026-01-01' AND payment_date <= '2026-06-30';

SELECT COUNT(*) as trial_customer_count
FROM customers
WHERE account_type = 'trial';

SELECT COUNT(*) as cancelled_customers
FROM customers
WHERE account_type = 'cancelled';

SELECT SUM(discount_amount) AS total_discounts
FROM orders
WHERE order_date >= '2026-01-01' AND order_date < '2026-04-01';
